<script setup>import {ref} from 'vue';const email=ref('');const password=ref('');const show=ref(false);const notice=ref(false);function login(){localStorage.setItem('casil-demo-session','true');notice.value=true}</script><template><section class="page-hero"><span class="eyebrow">Client access  |  demo mode</span><h1>A private place<br/>for your photographs.</h1><p>This interface is a UI simulation only. Do not enter real account credentials.</p></section><section class="section login-layout"><form class="login-card" @submit.prevent="login"><h2>Client demo</h2><p class="muted">Enter any email and password to preview the gallery UI.</p><div class="field"><label for="email">Email</label><input id="email" v-model.trim="email" type="email" required autocomplete="off"/></div><div class="field"><label for="password">Password</label><div class="password-row"><input id="password" v-model="password" :type="show?'text':'password'" required autocomplete="new-password"/><button type="button" @click="show=!show">{{show?'Hide':'Show'}}</button></div></div><button class="button">Enter demo gallery</button><RouterLink to="/" class="text-link">Back to portfolio Back to public website</RouterLink><p v-if="notice" class="notice">Demo session active. <RouterLink to="/client-gallery-demo" class="text-link">Open client gallery  -> </RouterLink></p></form><div class="notice">Not real authentication: this page does not verify identity or protect photos. The demo session flag can be bypassed and no password is saved.</div></section></template>
